import{H as e,Q as t,Ut as n,gt as r,nt as i,rt as a,tt as o}from"./chunks/framework.C6KOWIh-.js";import"./chunks/assets.M7-Gz8W6.js";var s=JSON.parse(`{"title":"Architecture","description":"","frontmatter":{"permalink":"/docs/getting-started/architecture/"},"headers":[],"relativePath":"docs/getting-started/architecture.md","filePath":"docs/getting-started/architecture.md"}`),c={name:`docs/getting-started/architecture.md`};function l(e,s,c,l,u,d){return r(),o(`div`,null,[s[2]||=i(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><p>The architecture of the Service Lifecycle Management consists of serveral components:</p><p><img src="/slm/img/figures/architecture.svg" alt="Architecture" data-zoomable="true"></p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to “Components”">​</a></h2><h3 id="discovery-server" tabindex="-1">Discovery Server <a class="header-anchor" href="#discovery-server" aria-label="Permalink to “Discovery Server”">​</a></h3><p>As <code>Discovery Server</code> <a href="https://www.consul.io" target="_blank" rel="noreferrer">Consul</a> from HashiCorp is used. It provides the following functionalities:</p><ul><li>List resources</li><li>List services</li><li>List backend components</li><li>Health monitoring of backend components</li></ul><h3 id="config-server" tabindex="-1">Config Server <a class="header-anchor" href="#config-server" aria-label="Permalink to “Config Server”">​</a></h3><p>As <code>Config Server</code> <a href="https://www.consul.io" target="_blank" rel="noreferrer">Consul</a> KV value store is used. It provides the following functionalities:</p><ul><li>Central provisioning of runtime configuration</li><li>Distribution of service configuration</li></ul><h3 id="credential-manager" tabindex="-1">Credential Manager <a class="header-anchor" href="#credential-manager" aria-label="Permalink to “Credential Manager”">​</a></h3><p>As <code>Credential Manager</code> <a href="https://www.vaultproject.io" target="_blank" rel="noreferrer">Vault</a> from HashiCrop is used. It provides the following functionalities: Provided functionalities:</p><ul><li>Management of SSH credentials</li><li>PKI certificate authority</li><li>Docker registry credentials</li><li>Service credentials</li></ul><h3 id="configuration-manager" tabindex="-1">Configuration Manager <a class="header-anchor" href="#configuration-manager" aria-label="Permalink to “Configuration Manager”">​</a></h3><p>As <code>Configuration manager</code> <a href="https://github.com/ansible/awx" target="_blank" rel="noreferrer">AWX</a> from ReaHat is used. It provides the following functionalities: Provided functionalities:</p><ul><li>Setup of Deployment Capabilites</li><li>Deployment of services</li></ul><h3 id="identity-and-access-management" tabindex="-1">Identity and Access Management <a class="header-anchor" href="#identity-and-access-management" aria-label="Permalink to “Identity and Access Management”">​</a></h3><p>For <code>Identity and Access Management</code> <a href="https://www.keycloak.org" target="_blank" rel="noreferrer">Keycloak</a> is used. It provides the following functionalities: Provided functionalities:</p><ul><li>User Management</li><li>Access Control</li><li>Permissions and role Management</li></ul><h3 id="message-queue" tabindex="-1">Message Queue <a class="header-anchor" href="#message-queue" aria-label="Permalink to “Message Queue”">​</a></h3><p>As <code>Message Queue</code> <a href="https://www.rabbitmq.com" target="_blank" rel="noreferrer">RabbitMQ</a> is used. It provides the following functionalities:</p><ul><li>Asynchronous communication between backend components</li><li>Reliable distribution of events and messages</li></ul><h3 id="reverse-proxy" tabindex="-1">Reverse Proxy <a class="header-anchor" href="#reverse-proxy" aria-label="Permalink to “Reverse Proxy”">​</a></h3><p>As <code>Reverse Proxy</code> <a href="https://traefik.io/traefik/" target="_blank" rel="noreferrer">Traefik</a> is used. It provides the following functionalities:</p><ul><li>Central entry point for external HTTP(S) traffic</li><li>Routing of requests to the corresponding backend components</li><li>TLS termination for secured access to APIs and UI</li></ul><h3 id="service-management" tabindex="-1">Service Management <a class="header-anchor" href="#service-management" aria-label="Permalink to “Service Management”">​</a></h3><p>The <code>Service Management</code> is a custom implementation. It provides the following functionalities: Provided functionalities:</p><ul><li>Catalog of service offerings</li><li>Orchestration of service (un)deployments</li></ul><h3 id="resource-management" tabindex="-1">Resource Management <a class="header-anchor" href="#resource-management" aria-label="Permalink to “Resource Management”">​</a></h3><p>The <code>Resource Management</code> is a custom implementation. It provides the following functionalities:</p><ul><li>Discovery of resources</li><li>Management of resources</li><li>Management of Deployment Capabilites</li><li>Firmware update of resources</li></ul><h3 id="platform-management" tabindex="-1">Platform Management <a class="header-anchor" href="#platform-management" aria-label="Permalink to “Platform Management”">​</a></h3><p>The <code>Platform Management</code> is a custom implementation. It provides the following functionalities:</p><ul><li>Management of users</li><li>Coordination of user provisioning</li><li>Management of credential metadata and links</li></ul><h3 id="notification-service" tabindex="-1">Notification Service <a class="header-anchor" href="#notification-service" aria-label="Permalink to “Notification Service”">​</a></h3><p>The <code>Notification Service</code> is a custom implementation. It provides the following functionalities:</p><ul><li>Delivery of notifications for platform events</li><li>Distribution of user-relevant status information</li></ul><h3 id="information-service" tabindex="-1">Information Service <a class="header-anchor" href="#information-service" aria-label="Permalink to “Information Service”">​</a></h3><p>The <code>Information Service</code> is a custom implementation. It provides the following functionalities:</p><ul><li>Provision of aggregated platform information</li><li>Read-oriented access to system information</li></ul><h3 id="ui" tabindex="-1">UI <a class="header-anchor" href="#ui" aria-label="Permalink to “UI”">​</a></h3><p>The <code>UI</code> is a custom implementation. It provides the following functionalities:</p><ul><li>User interface</li><li>Web-based</li></ul><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to “HTTPS”">​</a></h2><p>In SLM, <code>Traefik</code> is used as the reverse proxy and TLS termination point for inbound HTTPS traffic. External clients connect to Traefik, and Traefik forwards requests to the internal components (e.g., UI, Resource Management, Service Management).</p><p>Certificate management is handled by <code>Vault</code>, which acts as the PKI for the SLM. Vault contains a dedicated SLM root certificate authority (Root CA). From this Root CA, an Intermediate CA is derived and used for issuing certificates to SLM backend components. Traefik obtains a short-lived leaf certificate from this PKI chain, which supports regular certificate rotation with reduced operational overhead.</p><p>If you need to expose SLM with your own public or enterprise certificate chain, a common approach is to place an additional proxy in front of Traefik. This proxy can handle TLS termination with your public or enterprise certificate, while Traefik continues to manage the internal certificates for SLM components.</p><p>If the SLM Root CA is added as a trusted CA on your operating system and in your browser, HTTPS communication with SLM is considered trusted on that client.</p>`,48),t(`p`,null,[s[0]||=a(`The SLM Root CA certificate can be downloaded from `,-1),t(`code`,null,`http://<<your-slm-hostname>:`+n(e.$slm.ports.vault)+`/v1/pki_root_slm/cert/ca`,1),s[1]||=a(`.`,-1)])])}var u=e(c,[[`render`,l]]);export{s as __pageData,u as default};